window.MESA={"order":["reparacion","irrompibilidad","fortuna","toque_seda","eficiencia","filo","proteccion","botin","espinas","infinidad","paso_helado","aspecto_igneo","lealtad","sigilo"],"max":{"reparacion":77,"irrompibilidad":77,"fortuna":72,"toque_seda":78,"eficiencia":77,"filo":75,"proteccion":75,"botin":74,"espinas":76,"infinidad":74,"paso_helado":74,"aspecto_igneo":74,"lealtad":79,"sigilo":73},"mean":{"reparacion":20.0,"irrompibilidad":20.0,"fortuna":19.75,"toque_seda":20.0,"eficiencia":20.0,"filo":20.0,"proteccion":20.25,"botin":20.0,"espinas":20.0,"infinidad":20.0,"paso_helado":20.0,"aspecto_igneo":20.0,"lealtad":20.25,"sigilo":19.75},"enchants":{"reparacion":{"nombre":"Reparación","subtitulo":"Encantamiento del cuidado","frase":"Si algo se rompe, me remango y lo dejo mejor que antes.","descripcion":"Eres de las personas que notan el mal día de alguien antes de que lo diga. Te sale natural pegar lo que se quebró, ya sea un proyecto, una amistad o un ánimo por los suelos. Te recuperas rápido de los tropiezos y, cuando te caes, te levantas con una curita y sin drama. Eso sí, a veces te cuesta aceptar que no todo tiene arreglo.","fortalezas":["Sabes escuchar y consolar sin hacer sentir mal a nadie","Te levantas rápido después de un error o un golpe","Encuentras soluciones pacientes donde otros ya tirarían la toalla"],"debilidades":["Te cargas con los problemas ajenos y se te olvida cuidarte a ti","Insistes en arreglar cosas o vínculos que quizá ya cumplieron su ciclo"],"como_te_ven":"Te ven como la persona a la que se le llama cuando todo sale mal, porque contigo el desastre se siente más chiquito.","combina_con":[{"id":"lealtad","razon":"Los dos cuidan a su gente, y juntos nadie se queda sin apoyo."},{"id":"infinidad","razon":"Ella inventa mil cosas y tú las rescatas cuando se tuercen."}],"herramienta_ideal":"Pico de hierro, porque con tantas horas de minería y un poco de mantenimiento nunca te deja tirado.","color":"#7ef0c4"},"irrompibilidad":{"nombre":"Irrompibilidad","subtitulo":"Encantamiento de la constancia","frase":"Puedo tardar más, pero yo no me rindo a la mitad.","descripcion":"Cuando decides algo, ahí te quedas, con lluvia, con sueño o con todos diciéndote que mejor lo dejes. Tu fuerza no hace ruido: es la de quien sigue caminando mientras los demás se sientan a quejarse. Prefieres las cosas probadas y los hábitos que funcionan. A veces tu terquedad se pasa de la raya y sigues empujando una puerta que decía jalar.","fortalezas":["Terminas lo que empiezas, aunque se ponga pesado","Mantienes la calma y el ritmo cuando todos se desesperan","Eres confiable: si dices que sí, es que sí"],"debilidades":["Te cuesta cambiar de plan aunque ya no esté funcionando","Aguantas tanto que a veces nadie se entera de que ya estás cansado"],"como_te_ven":"Te ven como una roca amable: nadie sabe cómo lo haces, pero siempre sigues ahí.","combina_con":[{"id":"proteccion","razon":"Entre los dos arman un muro que ninguna tormenta mueve."},{"id":"paso_helado","razon":"Ella te enseña a rodear el obstáculo cuando no hay que chocar con él."}],"herramienta_ideal":"Pala de diamante, porque cava el mismo hoyo mil veces y ni se inmuta.","color":"#9aa5b8"},"fortuna":{"nombre":"Fortuna","subtitulo":"Encantamiento de la buena racha","frase":"Algo bueno viene en camino, solo hay que seguir moviéndose.","descripcion":"Tú ves una puerta cerrada y piensas que seguro hay una ventana abierta. Tu optimismo no es ingenuo, es una forma de estar atento a lo que otros dejan pasar: la oportunidad, el contacto, la casualidad que sale a favor. Contagias ganas con facilidad. Pero a veces confías tanto en que todo saldrá bien que se te escapan los detalles aburridos que sí importaban.","fortalezas":["Detectas oportunidades donde otros solo ven problemas","Levantas el ánimo del grupo sin esforzarte","Te atreves a probar cosas nuevas sin quedarte paralizado"],"debilidades":["Dejas pendientes importantes porque supones que se arreglarán solos","Te cuesta tomarte en serio los avisos de que algo podría salir mal"],"como_te_ven":"Te ven como la persona con suerte de la que todos quieren estar cerca, aunque tú sabes que también te lanzas a buscarla.","combina_con":[{"id":"botin","razon":"Juntos salen a explorar y siempre vuelven con algo brillante."},{"id":"sigilo","razon":"Ella mira antes de saltar y tú pones las ganas de saltar."}],"herramienta_ideal":"Caña de pescar, porque lanzas el anzuelo con una sonrisa y casi siempre algo muerde.","color":"#ffd36e"},"toque_seda":{"nombre":"Toque de seda","subtitulo":"Encantamiento del cuidado fino","frase":"Hay cosas que valen la pena hacerse despacio y bien.","descripcion":"Para ti los detalles no son un capricho, son la diferencia entre algo bonito y algo que solo funciona. Te gusta que las cosas se conserven tal cual son, sin rasguños ni apuros, y lo notas cuando algo está fuera de lugar por un milímetro. Tu delicadeza se nota en cómo tratas objetos, proyectos y personas. El riesgo es que te quedes puliendo para siempre algo que ya estaba listo.","fortalezas":["Tu trabajo se nota cuidado, con acabados que dan gusto","Tratas a las personas y a sus cosas con mucho tacto","Notas errores pequeños que a todos los demás se les pasan"],"debilidades":["Te cuesta entregar algo si sientes que todavía no está perfecto","Te incomoda que alguien más toque tu orden o cambie tus cosas"],"como_te_ven":"Te ven como alguien de buen gusto y mano suave, a quien da miedo y honor prestarle algo valioso.","combina_con":[{"id":"sigilo","razon":"Los dos observan antes de tocar, y se entienden sin hablar mucho."},{"id":"eficiencia","razon":"Ella aporta rapidez y tú las ganas de que todo salga bonito."}],"herramienta_ideal":"Pico de oro, porque nadie lo usa para romper rápido y todos lo usan para sacar algo intacto.","color":"#e8d8ff"},"eficiencia":{"nombre":"Eficiencia","subtitulo":"Encantamiento del buen sistema","frase":"Dame una lista, un plan y veinte minutos, y ya acabé.","descripcion":"Tu cerebro busca el camino más corto casi sin querer. Armas listas, atajos y pequeños sistemas que hacen que todo fluya y que los demás se pregunten cómo es que te da tiempo. Odias el trabajo dado vueltas y las reuniones que pudieron ser un mensaje. Solo ten cuidado, porque a veces la prisa te hace pasar por encima de quienes todavía iban pensando.","fortalezas":["Organizas el caos en pasos claros que se pueden seguir","Resuelves rápido sin perderte en detalles que no importan","Ahorras tiempo a todos con tus atajos y tus sistemas"],"debilidades":["Puedes verte impaciente con quien necesita más tiempo para decidir","A veces sacrificas el paseo y la sorpresa por llegar más rápido"],"como_te_ven":"Te ven como la persona que ya lo tenía resuelto desde antes de que el grupo terminara de preguntar.","combina_con":[{"id":"infinidad","razon":"Ella trae ideas por montones y tú las conviertes en proyectos terminados."},{"id":"filo","razon":"Los dos van directo al grano y no pierden tiempo en rodeos."}],"herramienta_ideal":"Hacha de netherita, porque tala un árbol entero antes de que otro acomode su inventario.","color":"#5ec8ff"},"filo":{"nombre":"Filo","subtitulo":"Encantamiento de la franqueza","frase":"Digo lo que pienso, y lo digo para que me hagan mejor.","descripcion":"Contigo no hay que adivinar nada: lo que piensas lo dices, con la cara de frente y sin vueltas. Te gusta competir, medirte y ganar, y eso te impulsa a mejorar más que a casi nadie. Valoras que la gente sea clara contigo igual que tú con ella. A veces tu honestidad llega más rápido que tu tacto, y alguien sale raspado sin que lo hayas querido.","fortalezas":["Eres claro y honesto, así que nadie tiene que adivinar contigo","Tu espíritu competitivo te empuja a superarte una y otra vez","Tomas decisiones sin darle vueltas eternas al asunto"],"debilidades":["Dices las cosas tan directo que a veces hieres sin querer","Te cuesta perder con elegancia cuando de verdad te importaba ganar"],"como_te_ven":"Te ven como alguien que no se anda con rodeos, que a veces asusta un poco, pero a quien todos creen.","combina_con":[{"id":"lealtad","razon":"Ella suaviza tus aristas y tú le das valor para decir lo que calla."},{"id":"eficiencia","razon":"Los dos quieren resultados, y juntos los consiguen antes del almuerzo."}],"herramienta_ideal":"Espada de diamante, porque no tiene dudas sobre lo que quiere cortar.","color":"#ff4d4d"},"proteccion":{"nombre":"Protección","subtitulo":"Encantamiento del escudo","frase":"Yo me adelanto al problema para que nadie tenga que sufrirlo.","descripcion":"Antes de salir, ya revisaste que todos tengan lo necesario, y por eso el grupo se siente seguro contigo cerca. Prefieres prevenir que lamentar, y eso te hace estable en medio del desorden. Piensas en el \"y si pasa\" para que los demás no tengan que hacerlo. Lo difícil es soltar el control: no todo riesgo se puede evitar, y a veces sobreprotegerlos los priva de aprender.","fortalezas":["Piensas en los riesgos antes de que se vuelvan problemas","Das estabilidad y calma a quienes están a tu alrededor","Pones a tu gente por delante cuando se pone difícil"],"debilidades":["Te cuesta dejar que otros se equivoquen y aprendan por su cuenta","Cargas con demasiada responsabilidad y te olvidas de pedir ayuda"],"como_te_ven":"Te ven como el escudo del grupo: quien dice que no pasará nada porque sabe que tú ya revisaste.","combina_con":[{"id":"irrompibilidad","razon":"Los dos son firmes, y juntos aguantan cualquier temporal."},{"id":"aspecto_igneo","razon":"Ella pone la chispa y tú te aseguras de que nadie se queme."}],"herramienta_ideal":"Escudo, porque su razón de ser es que los demás avancen mientras tú cubres la retaguardia.","color":"#3f7bff"},"botin":{"nombre":"Botín","subtitulo":"Encantamiento del coleccionista","frase":"Siempre hay un rincón más por explorar y algo más que guardar.","descripcion":"Tu curiosidad no se apaga: abres el cajón que no era tuyo, pruebas el camino que nadie tomó y vuelves con los bolsillos llenos de cosas que a lo mejor servirán. Disfrutas coleccionar, ya sea objetos, datos, experiencias o logros. Tienes hambre de más y eso te mantiene en movimiento. Lo complicado es saber cuándo ya tienes suficiente, porque tu cuarto, tu lista de pendientes y tu inventario lo saben.","fortalezas":["Exploras con ganas y descubres cosas que nadie más vio","Tu ambición te empuja a buscar siempre un siguiente nivel","Sabes reunir recursos y contactos que luego le sirven a todos"],"debilidades":["Acumulas tanto que te cuesta soltar o decidir qué sí vale la pena","Te distrae lo nuevo y dejas a medias lo que ya tenías en la mano"],"como_te_ven":"Te ven como el explorador que siempre regresa con una historia y algo curioso en el bolsillo.","combina_con":[{"id":"fortuna","razon":"Los dos creen que lo mejor está a la vuelta, así que van juntos a buscarlo."},{"id":"proteccion","razon":"Ella cuida el campamento mientras tú te lanzas a descubrir."}],"herramienta_ideal":"Espada de hierro, porque te acompaña a cada mazmorra y siempre vuelve con algo extra.","color":"#e0a458"},"espinas":{"nombre":"Espinas","subtitulo":"Encantamiento de los límites","frase":"Soy amable hasta que cruzas la raya, y esa raya es firme.","descripcion":"Eres suave por defecto, pero con bordes bien puestos: sabes dónde acaba lo que toleras y no te da pena decirlo. Si alguien te falta al respeto, tu respuesta le llega de vuelta, rápido y sin pedir permiso. Eso te protege de que te pisoteen y hace que los demás te respeten. A veces levantas las espinas antes de tiempo y alguien con buenas intenciones sale pinchado.","fortalezas":["Pones límites claros y los sostienes sin perder la calma","No te dejas manipular ni presionar para hacer lo que no quieres","Defiendes tu espacio y el de los tuyos con mucha firmeza"],"debilidades":["Te pones a la defensiva incluso cuando nadie quería lastimarte","Te cuesta bajar la guardia y dejar que alguien se acerque de verdad"],"como_te_ven":"Te ven como alguien a quien conviene tratar con cariño, porque si te hacen daño, el recuerdo les pica.","combina_con":[{"id":"lealtad","razon":"Ella te enseña que bajar la guardia con la gente correcta es seguro."},{"id":"paso_helado","razon":"Con su calma, ayuda a que no levantes las espinas por cualquier cosa."}],"herramienta_ideal":"Armadura de hierro, porque la gente se lo piensa dos veces antes de tocarla.","color":"#4caf50"},"infinidad":{"nombre":"Infinidad","subtitulo":"Encantamiento de las mil ideas","frase":"Tengo más ideas que horas, y cada una merece intentarse.","descripcion":"Tu cabeza es una fábrica que no cierra: dibujas, programas, inventas y mezclas cosas que nadie había juntado antes. Cuando te quedas sin un recurso, creas otro, y cuando se acaba un proyecto ya traes tres más en la mochila. Tu energía creativa es difícil de agotar y contagia. El problema es que no todas esas ideas llegan a la meta, y a veces te distraes con la siguiente antes de terminar la de hoy.","fortalezas":["Se te ocurren soluciones y mezclas que a nadie más se le ocurrirían","Nunca te quedas sin recursos ni sin ganas de intentar algo","Inspiras a los demás a atreverse a crear sin miedo"],"debilidades":["Dejas proyectos a medias porque ya te emocionó otro","Te cuesta elegir una sola idea cuando todas te parecen geniales"],"como_te_ven":"Te ven como la persona que siempre trae algo nuevo entre manos y cuyas ideas hay que escuchar hasta el final.","combina_con":[{"id":"eficiencia","razon":"Ella ordena tus ideas y las lleva hasta la línea de meta."},{"id":"reparacion","razon":"Tú creas sin miedo y ella te ayuda a recoger los pedazos si algo sale mal."}],"herramienta_ideal":"Arco, porque dispara flechas que no se acaban y siempre encuentras otra forma de usarlas.","color":"#b36bff"},"paso_helado":{"nombre":"Paso helado","subtitulo":"Encantamiento de la calma que adapta","frase":"Si no hay camino, lo congelo y cruzo por encima del lago.","descripcion":"Donde otros ven un obstáculo, tú ves un terreno distinto al que hay que acostumbrarse. Mantienes la cabeza fría cuando todo se mueve y encuentras el paso que nadie había visto. Te adaptas a gente, planes y cambios de último minuto sin hacer un drama. A veces tanta flexibilidad te hace parecer indeciso, o te lleva a ceder más de lo que querías con tal de que fluya.","fortalezas":["Te adaptas rápido a cambios de plan sin perder la serenidad","Encuentras rutas alternativas cuando el camino principal se cierra","Tu calma ayuda a que los demás respiren y piensen mejor"],"debilidades":["Cedes con facilidad y a veces callas lo que de verdad prefieres","Te cuesta comprometerte con una sola ruta si hay varias abiertas"],"como_te_ven":"Te ven como alguien tranquilo que siempre sale bien parado, aunque nadie sepa cómo lo hiciste.","combina_con":[{"id":"espinas","razon":"Ella pone los límites que tú a veces olvidas y tú le bajas la tensión."},{"id":"aspecto_igneo","razon":"Su fuego y tu frescura se equilibran cuando uno se pasa de intensidad."}],"herramienta_ideal":"Botas de diamante, porque te llevan por cualquier terreno sin que lo pienses dos veces.","color":"#8ff0ff"},"aspecto_igneo":{"nombre":"Aspecto ígneo","subtitulo":"Encantamiento de la pasión","frase":"Si algo me importa, lo vivo a tope y se lo contagio a todos.","descripcion":"Tú no haces las cosas a medias: cuando algo te late, se nota en tus ojos, en tu voz y en la energía con la que te lanzas. Tu entusiasmo enciende a los demás y convierte planes aburridos en aventuras. Sientes fuerte, ríes fuerte y también te enojas fuerte. Eso a veces te quema por dentro o a quien está cerca, y se te va rápido la llama cuando algo deja de emocionarte.","fortalezas":["Tu entusiasmo contagia y pone en marcha a todo el grupo","Te entregas por completo a lo que te apasiona","Tienes un carisma que hace que los demás quieran seguirte"],"debilidades":["Te enciendes con tanta intensidad que a veces te pasas de la raya","Pierdes interés rápido cuando la emoción inicial se apaga"],"como_te_ven":"Te ven como la chispa de cada reunión: imposible no notarte, difícil no contagiarse.","combina_con":[{"id":"proteccion","razon":"Ella cuida que tu fuego caliente a todos sin quemar a nadie."},{"id":"paso_helado","razon":"Su serenidad enfría los momentos en que la intensidad se desborda."}],"herramienta_ideal":"Espada de netherita, porque brilla más cuando la agitas con ganas y deja una estela a su paso.","color":"#ff8a00"},"lealtad":{"nombre":"Lealtad","subtitulo":"Encantamiento del vínculo","frase":"Puedo irme lejos, pero siempre vuelvo con mi gente.","descripcion":"Tus amistades no son un número, son un hogar al que siempre tienes ganas de regresar. Recuerdas lo que le importa a cada quien, apareces cuando hace falta y no abandonas a nadie por conveniencia. Valoras más un vínculo que una victoria. Pero tanta fidelidad a veces te hace aguantar relaciones que ya no te hacen bien, o sentirte herido si no te corresponden igual.","fortalezas":["Estás presente en los momentos difíciles de la gente que quieres","Recuerdas detalles que hacen sentir especial a cada persona","Construyes relaciones que duran años y se sienten seguras"],"debilidades":["Te cuesta soltar vínculos que ya no te hacen bien","Te duele en silencio cuando sientes que das más de lo que recibes"],"como_te_ven":"Te ven como el amigo con el que siempre se puede contar, aunque pase el tiempo y cambie todo.","combina_con":[{"id":"filo","razon":"Con su franqueza te ayuda a decir lo que callas por cuidar a todos."},{"id":"reparacion","razon":"Los dos sostienen a su gente y juntos arreglan lo que se enreda."}],"herramienta_ideal":"Tridente, porque siempre regresa a tu mano por más lejos que lo lances.","color":"#ff8fc7"},"sigilo":{"nombre":"Sigilo veloz","subtitulo":"Encantamiento de la mirada atenta","frase":"Observo primero, y cuando me muevo ya sé a dónde voy.","descripcion":"Antes de hablar, miras; antes de actuar, piensas. Notas cosas que otros pasan por alto, como un gesto, un detalle o un cambio de humor, y las guardas para cuando de verdad importen. Te mueves por el mundo sin hacer ruido y eso te permite llegar a donde otros tropiezan. Pero tu reserva a veces se confunde con frialdad, y algunas veces piensas tanto que la oportunidad pasa de largo.","fortalezas":["Observas y entiendes situaciones antes de meterte en ellas","Piensas con calma, así que rara vez tomas decisiones a ciegas","Sabes guardar secretos y moverte sin llamar la atención"],"debilidades":["Piensas tanto que a veces la oportunidad se va antes de que actúes","Tu reserva puede hacer que los demás no sepan qué sientes de verdad"],"como_te_ven":"Te ven como alguien misterioso y tranquilo que se entera de todo sin que nadie le haya dicho nada.","combina_con":[{"id":"fortuna","razon":"Su optimismo te empuja a dar el salto que tu cabeza tarda en aprobar."},{"id":"toque_seda","razon":"Los dos aprecian el silencio y los detalles, y trabajan sin estorbarse."}],"herramienta_ideal":"Botas de cuero, porque con ellas caminas sin que nadie te escuche llegar.","color":"#6b5bd2"}},"questions":[{"b":1,"th":"Social","t":"Vas a organizar una reunión con tus amigos. ¿Cómo la planeas?","o":[{"e":"irrompibilidad","s":"proteccion","t":"Mantengo la tradición de siempre: mismo día, mismo lugar, pase lo que pase."},{"e":"infinidad","s":"botin","t":"Invento un tema nuevo, con juegos y dinámicas que a nadie se le han ocurrido."},{"e":"eficiencia","s":"filo","t":"Armo el grupo, reparto tareas y dejo todo listo en cinco minutos."},{"e":"fortuna","s":"infinidad","t":"Invito a todos sin darle tantas vueltas; seguro saldrá algo bueno y divertido."}]},{"b":1,"th":"Social","t":"Entras a un servidor de Minecraft donde no conoces a nadie. ¿Qué haces primero?","o":[{"e":"reparacion","s":"lealtad","t":"Busco a quien parezca perdido o desanimado y le ofrezco una mano con lo que necesite."},{"e":"botin","s":"fortuna","t":"Recorro el mapa preguntando por aldeas, tesoros y rincones que valga la pena descubrir."},{"e":"irrompibilidad","s":"eficiencia","t":"Sigo mi rutina de siempre, constante, hasta que todos se acostumbran a verme por ahí."},{"e":"paso_helado","s":"reparacion","t":"Observo cómo se llevan y me acomodo al ambiente de cada grupo con naturalidad."}]},{"b":1,"th":"Social","t":"Llegas a una fiesta donde casi no conoces a nadie. ¿Qué haces?","o":[{"e":"sigilo","s":"paso_helado","t":"Observo desde un rincón, escucho un rato y me acerco cuando entiendo el ambiente."},{"e":"aspecto_igneo","s":"espinas","t":"Me lanzo a la pista, presento a todos y la energía se contagia sola."},{"e":"lealtad","s":"aspecto_igneo","t":"Busco al amigo que sí conozco y nos quedamos juntos toda la noche."},{"e":"reparacion","s":"paso_helado","t":"Detecto a alguien que se ve incómodo y me siento a platicar con esa persona."}]},{"b":1,"th":"Social","t":"¿Cuál de estas frases te describe mejor dentro de un grupo de amigos?","o":[{"e":"filo","s":"aspecto_igneo","t":"Soy quien dice lo que piensa y siempre quiere ganar en cualquier juego."},{"e":"proteccion","s":"irrompibilidad","t":"Soy quien se fija en que todos lleguen bien y nadie se quede atrás."},{"e":"eficiencia","s":"toque_seda","t":"Soy quien organiza el plan y los horarios para que todo funcione sin enredos."},{"e":"infinidad","s":"fortuna","t":"Soy quien llega con ideas nuevas para cada salida, juego o broma."}]},{"b":1,"th":"Social","t":"En tu mundo compartido de Minecraft, un amigo destruye tu construcción a propósito. ¿Qué haces?","o":[{"e":"reparacion","s":"proteccion","t":"Lo hablamos con calma y le propongo reconstruirlo juntos para dejarlo mejor que antes."},{"e":"espinas","s":"sigilo","t":"Le dejo muy claro que no se repite, y si lo hace, se lo cobro."},{"e":"irrompibilidad","s":"eficiencia","t":"Respiro, vuelvo a construir sin quejarme y sigo jugando como si nada me frenara."},{"e":"fortuna","s":"botin","t":"Me río; seguro fue un accidente y hasta nos sirve para rediseñarlo mejor."}]},{"b":1,"th":"Social","t":"¿Qué valoras más cuando conoces a una persona nueva?","o":[{"e":"espinas","s":"filo","t":"Que respete mis límites desde el principio y no intente cambiarme."},{"e":"toque_seda","s":"sigilo","t":"Que note los detalles y trate con cuidado lo que le confío."},{"e":"lealtad","s":"reparacion","t":"Que quiera quedarse a largo plazo y sea alguien con quien siempre pueda contar."},{"e":"botin","s":"infinidad","t":"Que tenga historias que contar y me abra la puerta a gente y lugares nuevos."}]},{"b":1,"th":"Social","t":"Un amigo te invita por primera vez a su mundo de Minecraft. ¿Cómo te comportas?","o":[{"e":"toque_seda","s":"irrompibilidad","t":"Camino con cuidado y no toco nada de su construcción sin preguntarle antes."},{"e":"lealtad","s":"aspecto_igneo","t":"Me quedo a su lado y lo acompaño a donde vaya, aunque sea aburrido."},{"e":"botin","s":"infinidad","t":"Exploro cada rincón del mundo buscando cuevas, aldeas y cosas que aún me faltan."},{"e":"espinas","s":"sigilo","t":"Pregunto cuáles son las reglas de su casa y también dejo claras las mías."}]},{"b":1,"th":"Social","t":"Se cancela de último minuto el plan que tenías con tus amigos. ¿Cómo reaccionas?","o":[{"e":"eficiencia","s":"toque_seda","t":"Propongo un plan B ahí mismo, con lugar y hora, y listo."},{"e":"lealtad","s":"proteccion","t":"Les digo que da igual el lugar; lo importante es que sigamos juntos."},{"e":"paso_helado","s":"reparacion","t":"Sin drama, me ajusto a lo que salga y encuentro otro plan sobre la marcha."},{"e":"botin","s":"fortuna","t":"Aprovecho para ir a conocer ese sitio nuevo que tenía pendiente desde hace tiempo."}]},{"b":1,"th":"Social","t":"En una reunión, alguien empieza a burlarse de un amigo tuyo. ¿Qué haces?","o":[{"e":"proteccion","s":"lealtad","t":"Me pongo entre los dos y cambio el tema para cuidar a mi amigo."},{"e":"aspecto_igneo","s":"espinas","t":"Me enciendo y salto a defenderlo con toda la intensidad que tengo."},{"e":"sigilo","s":"espinas","t":"Observo en silencio, entiendo qué pasa y actúo después, sin hacer escena."},{"e":"filo","s":"eficiencia","t":"Le digo de frente, sin rodeos, que se está pasando de la raya."}]},{"b":1,"th":"Social","t":"Tu grupo de amigos lleva meses sin verse. ¿Qué haces al respecto?","o":[{"e":"reparacion","s":"paso_helado","t":"Los reúno y arreglo cualquier tensión pendiente para que vuelva la buena onda."},{"e":"toque_seda","s":"irrompibilidad","t":"Organizo algo pequeño, cuidado al detalle, para que todo sea como lo recordamos."},{"e":"aspecto_igneo","s":"botin","t":"Lanzo un mensaje lleno de entusiasmo y armo una gran reunión esta misma semana."},{"e":"proteccion","s":"lealtad","t":"Reviso cómo está cada quien y me aseguro de que el grupo siga firme."}]},{"b":2,"th":"Estrés y problemas","t":"Se cancela de golpe tu plan del fin de semana. ¿Qué haces?","o":[{"e":"eficiencia","s":"filo","t":"Aprovecho para tachar pendientes de mi lista y dejar todo ordenado."},{"e":"botin","s":"infinidad","t":"Busco algo nuevo que nunca haya probado y me lanzo a explorarlo."},{"e":"paso_helado","s":"reparacion","t":"Respiro, suelto el plan original y me dejo llevar por lo que salga."},{"e":"lealtad","s":"aspecto_igneo","t":"Llamo a mis amigos para ver quién se apunta a un plan distinto."}]},{"b":2,"th":"Estrés y problemas","t":"Cometes un error que afecta a todo tu equipo. ¿Qué haces?","o":[{"e":"reparacion","s":"proteccion","t":"Reconozco mi parte y me pongo a arreglarlo para que todos queden bien."},{"e":"sigilo","s":"toque_seda","t":"Guardo silencio un rato, analizo qué falló y solo entonces hablo."},{"e":"proteccion","s":"irrompibilidad","t":"Reviso que nadie salga perjudicado y dejo medidas para que no se repita."},{"e":"infinidad","s":"botin","t":"Se me ocurren mil formas de salir del paso y pruebo la más original."}]},{"b":2,"th":"Estrés y problemas","t":"Toda una semana te sale mal. ¿Cuál de estas actitudes te describe mejor?","o":[{"e":"irrompibilidad","s":"eficiencia","t":"Sigo adelante un día a la vez, sin soltar lo que empecé."},{"e":"lealtad","s":"aspecto_igneo","t":"Me apoyo en mi gente y también estoy ahí para la suya."},{"e":"filo","s":"espinas","t":"Digo lo que me molesta sin rodeos y ataco el problema de frente."},{"e":"fortuna","s":"paso_helado","t":"Confío en que algo bueno viene y estoy atento a la primera oportunidad."}]},{"b":2,"th":"Estrés y problemas","t":"En Minecraft cae la noche y estás lejos de casa, sin refugio. ¿Qué haces?","o":[{"e":"eficiencia","s":"filo","t":"Cavo un refugio rápido, lo tapo y sigo con lo que tenía pendiente."},{"e":"toque_seda","s":"sigilo","t":"Me refugio con mucho cuidado, procurando no estropear nada de lo que ya tengo."},{"e":"paso_helado","s":"sigilo","t":"Observo el terreno con calma y encuentro un camino que otros pasarían por alto."},{"e":"aspecto_igneo","s":"espinas","t":"Enciendo antorchas por todos lados y convierto la noche en una fiesta de luz."}]},{"b":2,"th":"Estrés y problemas","t":"Alguien te presiona para que cedas en algo que no quieres. ¿Qué haces?","o":[{"e":"infinidad","s":"fortuna","t":"Propongo una alternativa original que cambia por completo la conversación."},{"e":"espinas","s":"proteccion","t":"Le dejo claro mi límite y, si insiste, le respondo igual de firme."},{"e":"irrompibilidad","s":"reparacion","t":"Mantengo mi postura con paciencia, aunque me insistan durante días enteros."},{"e":"proteccion","s":"lealtad","t":"Cuido a los míos y busco un acuerdo estable que no se repita."}]},{"b":2,"th":"Estrés y problemas","t":"Te piden presentar algo importante sin tiempo para prepararlo. ¿Cómo respondes?","o":[{"e":"paso_helado","s":"infinidad","t":"Me adapto, respiro hondo y voy encontrando el camino mientras hablo."},{"e":"toque_seda","s":"eficiencia","t":"Pido unos minutos para cuidar cada detalle, aunque sea algo pequeño."},{"e":"irrompibilidad","s":"proteccion","t":"Lo hago paso a paso hasta terminar, sin importar cuánto me cueste."},{"e":"fortuna","s":"paso_helado","t":"Confío en que saldrá bien y lo veo como una oportunidad de lucirme."}]},{"b":2,"th":"Estrés y problemas","t":"Un creeper aparece justo al lado de tu casa en Minecraft. ¿Qué haces?","o":[{"e":"reparacion","s":"lealtad","t":"Si explota, reconstruyo con calma y dejo todo mejor que antes."},{"e":"sigilo","s":"toque_seda","t":"Me quedo quieto, observo sus movimientos y me alejo sin hacer ruido."},{"e":"proteccion","s":"irrompibilidad","t":"Me pongo entre él y mi casa para que nada se dañe."},{"e":"filo","s":"aspecto_igneo","t":"Voy directo a enfrentarlo y lo derroto antes de que reaccione."}]},{"b":2,"th":"Estrés y problemas","t":"Alguien rompe una promesa que te había hecho. ¿Cuál es tu reacción más típica?","o":[{"e":"lealtad","s":"reparacion","t":"Le doy otra oportunidad; un vínculo importa más que un error."},{"e":"aspecto_igneo","s":"filo","t":"Me enciendo, se lo digo con pasión y luego se me pasa rápido."},{"e":"botin","s":"fortuna","t":"Me lanzo a buscar nuevas opciones y a conocer gente que aporte más."},{"e":"espinas","s":"sigilo","t":"Le dejo claro que eso no se repite o pierde mi confianza."}]},{"b":2,"th":"Estrés y problemas","t":"Te quedas sin comida en lo más profundo de una cueva de Minecraft. ¿Qué haces?","o":[{"e":"eficiencia","s":"toque_seda","t":"Calculo la ruta más corta a la superficie y salgo sin desviarme."},{"e":"fortuna","s":"botin","t":"Sigo avanzando convencido de que encontraré algo útil a la vuelta."},{"e":"espinas","s":"filo","t":"Si algo me bloquea el paso, le devuelvo el golpe y sigo firme."},{"e":"botin","s":"fortuna","t":"Aprovecho para explorar más hondo; seguro hay minerales y tesoros por descubrir."}]},{"b":2,"th":"Estrés y problemas","t":"Cuando estás muy estresado, ¿qué te ayuda más a recuperar el ánimo?","o":[{"e":"botin","s":"infinidad","t":"Salir a descubrir un lugar nuevo o conseguir algo que llevaba tiempo queriendo."},{"e":"aspecto_igneo","s":"espinas","t":"Ponerme música a todo volumen y mover el cuerpo hasta soltar la energía."},{"e":"proteccion","s":"irrompibilidad","t":"Volver a mi rutina estable y rodearme de lo que me da seguridad."},{"e":"paso_helado","s":"sigilo","t":"Caminar sin prisa, dejar que la mente se enfríe y ver con claridad."}]},{"b":3,"th":"Estudio y trabajo","t":"Te asignan un proyecto grande y con pocas instrucciones. ¿Cómo lo empiezas?","o":[{"e":"fortuna","s":"botin","t":"Me emociona: seguro sale algo bueno y en el camino aparecerán oportunidades."},{"e":"toque_seda","s":"eficiencia","t":"Reviso cada detalle con calma para que el primer borrador ya quede impecable."},{"e":"irrompibilidad","s":"proteccion","t":"Fijo un ritmo diario y avanzo sin soltarlo hasta terminarlo, cueste lo que cueste."},{"e":"paso_helado","s":"infinidad","t":"Respiro, miro con qué cuento y voy ajustando el plan sobre la marcha."}]},{"b":3,"th":"Estudio y trabajo","t":"Hay un concurso entre equipos en tu escuela o trabajo. ¿Cómo lo vives?","o":[{"e":"filo","s":"eficiencia","t":"Voy a ganar y lo digo claro; competir me saca lo mejor."},{"e":"sigilo","s":"toque_seda","t":"Observo en silencio a los demás y planeo mi jugada antes de moverme."},{"e":"aspecto_igneo","s":"filo","t":"Me emociono tanto que le contagio las ganas a todo el equipo."},{"e":"reparacion","s":"paso_helado","t":"Cuido que mi equipo descanse y se levante el ánimo después de cada ronda."}]},{"b":3,"th":"Estudio y trabajo","t":"En Minecraft, tú y tus amigos empiezan una base nueva. ¿Qué haces primero?","o":[{"e":"proteccion","s":"lealtad","t":"Levanto muros y pongo antorchas alrededor para que todos duerman tranquilos."},{"e":"filo","s":"espinas","t":"Propongo un reto: quien construya mejor su parte gana, y yo voy por ese título."},{"e":"fortuna","s":"paso_helado","t":"Elijo un lugar al azar, confiado en que cerca habrá algo bueno."},{"e":"eficiencia","s":"irrompibilidad","t":"Hago una lista de materiales, reparto tareas y empiezo a construir de inmediato."}]},{"b":3,"th":"Estudio y trabajo","t":"Faltan dos días para la fecha límite y el trabajo va atrasado. ¿Qué haces?","o":[{"e":"sigilo","s":"toque_seda","t":"Me aparto un rato, analizo qué falta exactamente y actúo en silencio, sin alboroto."},{"e":"eficiencia","s":"toque_seda","t":"Priorizo lo esencial, descarto lo demás y trabajo en bloques cortos y rápidos."},{"e":"lealtad","s":"aspecto_igneo","t":"Me quedo con mi equipo hasta el final; nadie carga solo con el pendiente."},{"e":"irrompibilidad","s":"reparacion","t":"Trabajo sin parar hasta acabarlo, aunque la noche se alargue y me canse."}]},{"b":3,"th":"Estudio y trabajo","t":"Es la lluvia de ideas del equipo. ¿Cuál es tu papel natural?","o":[{"e":"infinidad","s":"botin","t":"Suelto una idea tras otra, aunque la mitad sean locuras que luego se afinan."},{"e":"sigilo","s":"paso_helado","t":"Escucho todo con atención y al final propongo una sola idea, muy pensada."},{"e":"fortuna","s":"botin","t":"Apoyo cualquier propuesta con entusiasmo: confío en que alguna va a funcionar."},{"e":"espinas","s":"sigilo","t":"Si alguien descarta mi idea sin escucharla, se lo hago notar con firmeza."}]},{"b":3,"th":"Estudio y trabajo","t":"En una mina compartida, un jugador se lleva los minerales que tú marcaste. ¿Qué haces?","o":[{"e":"espinas","s":"proteccion","t":"Le advierto una sola vez; si insiste, se lo cobro sin dudarlo."},{"e":"aspecto_igneo","s":"filo","t":"Me enciendo y lo encaro con toda la intensidad: ¡esto se resuelve ya!"},{"e":"lealtad","s":"aspecto_igneo","t":"Llamo a mi equipo y lo enfrentamos juntos: nadie toca lo que es nuestro."},{"e":"botin","s":"fortuna","t":"Lo dejo y busco una veta todavía mejor; siempre quiero encontrar algo más."}]},{"b":3,"th":"Estudio y trabajo","t":"Tienes una tarde libre para estudiar o investigar algo. ¿Cómo la usas?","o":[{"e":"fortuna","s":"infinidad","t":"Abro algo al azar, convencido de que encontraré justo lo que me sirve."},{"e":"toque_seda","s":"irrompibilidad","t":"Elijo un tema pequeño y lo estudio a fondo, sin dejar ningún detalle."},{"e":"botin","s":"fortuna","t":"Abro mil pestañas y guardo todo lo que encuentro; siempre quiero saber más."},{"e":"reparacion","s":"lealtad","t":"Repaso lo que antes entendí a medias hasta dejarlo bien firme."}]},{"b":3,"th":"Estudio y trabajo","t":"Un amigo te pide ayuda con su tarea justo cuando tienes la tuya pendiente.","o":[{"e":"proteccion","s":"lealtad","t":"Lo ayudo a organizarse primero, para que no vuelva a quedar en aprietos."},{"e":"lealtad","s":"reparacion","t":"Dejo lo mío un rato: él cuenta conmigo y yo con él."},{"e":"infinidad","s":"fortuna","t":"Le propongo un método original que se me acaba de ocurrir para resolverla."},{"e":"toque_seda","s":"eficiencia","t":"Reviso su trabajo con mucho cuidado y le señalo cada detalle, respetando su estilo."}]},{"b":3,"th":"Estudio y trabajo","t":"Debes recoger materiales para tu equipo en Minecraft y la única cueva está llena de mobs. ¿Cómo entras?","o":[{"e":"sigilo","s":"espinas","t":"Avanzo despacio, pegado a las paredes, observando y evitando que me noten."},{"e":"paso_helado","s":"sigilo","t":"Busco otra ruta o armo un puente; siempre hay otro camino."},{"e":"espinas","s":"proteccion","t":"Entro tranquilo: quien me ataque se lleva el golpe de vuelta."},{"e":"filo","s":"aspecto_igneo","t":"Voy de frente con la espada: prefiero el combate directo y ganarlo."}]},{"b":3,"th":"Estudio y trabajo","t":"Entregas un trabajo y recibes una crítica fuerte. ¿Cómo reaccionas?","o":[{"e":"toque_seda","s":"irrompibilidad","t":"Releo todo con calma y pulo cada punto señalado hasta que quede perfecto."},{"e":"aspecto_igneo","s":"botin","t":"Me prende la motivación y lo rehago con más pasión que antes."},{"e":"reparacion","s":"paso_helado","t":"Me tomo un respiro para recuperar el ánimo y luego arreglo lo que falle."},{"e":"botin","s":"infinidad","t":"Pido opiniones a cuanta gente pueda: quiero juntar el máximo de mejoras posibles."}]},{"b":4,"th":"Creatividad","t":"Alguien te pide cambiar tu diseño para que quede a su gusto. ¿Qué haces?","o":[{"e":"toque_seda","s":"eficiencia","t":"Intento convencerlo de dejarlo tal cual lo pensé; cada detalle tiene su razón."},{"e":"espinas","s":"filo","t":"Le aclaro con firmeza que mi diseño no se toca, o que busque a otra persona."},{"e":"paso_helado","s":"reparacion","t":"Lo escucho con calma y busco una versión que funcione para los dos."},{"e":"botin","s":"fortuna","t":"Veo qué puedo ganar con el cambio: más presupuesto, nuevos proyectos o contactos."}]},{"b":4,"th":"Creatividad","t":"Te dan un mundo nuevo de Minecraft sin límites. ¿Cuál es tu plan ideal?","o":[{"e":"infinidad","s":"paso_helado","t":"Empiezo varias construcciones a la vez; ideas me sobran para llenar todo el mapa."},{"e":"eficiencia","s":"toque_seda","t":"Hago una lista, organizo mi base y construyo lo esencial lo antes posible."},{"e":"irrompibilidad","s":"reparacion","t":"Elijo una obra enorme y la sigo día tras día hasta terminarla."},{"e":"paso_helado","s":"sigilo","t":"Recorro el terreno con calma y adapto mis planes a lo que ofrece."}]},{"b":4,"th":"Creatividad","t":"Tu proyecto lleva semanas atorado. ¿Cómo lo sacas adelante?","o":[{"e":"fortuna","s":"botin","t":"Confío en que la solución aparece si sigo probando cosas; casi siempre pasa."},{"e":"lealtad","s":"aspecto_igneo","t":"Se lo cuento a mis amigos; juntos siempre encontramos cómo avanzar."},{"e":"infinidad","s":"botin","t":"Lo replanteo con otras diez ideas; siempre tengo algo más por intentar."},{"e":"irrompibilidad","s":"eficiencia","t":"Trabajo un poco cada día hasta que ceda; no pienso soltarlo."}]},{"b":4,"th":"Creatividad","t":"Tu equipo presenta una idea nueva en una reunión. ¿Cuál es tu papel?","o":[{"e":"fortuna","s":"infinidad","t":"Soy quien dice que va a salir genial y anima a probarla."},{"e":"aspecto_igneo","s":"espinas","t":"Hablo con tanta pasión que a todos les dan ganas de empezar ya."},{"e":"sigilo","s":"toque_seda","t":"Escucho y observo primero; hablo después, cuando ya vi el panorama completo."},{"e":"proteccion","s":"lealtad","t":"Señalo los riesgos y propongo un plan B para que nadie salga perjudicado."}]},{"b":4,"th":"Creatividad","t":"En Minecraft te retan a construir una casa en una hora con materiales al azar.","o":[{"e":"toque_seda","s":"irrompibilidad","t":"Elijo cada bloque con cuidado; prefiero entregar algo pequeño pero impecable."},{"e":"paso_helado","s":"infinidad","t":"Miro qué me tocó y le encuentro la forma de que funcione."},{"e":"infinidad","s":"fortuna","t":"Empiezo a inventar mil combinaciones; con lo que sea se me ocurre algo."},{"e":"fortuna","s":"paso_helado","t":"Confío en que algo genial va a salir, aunque aún no sepa qué."}]},{"b":4,"th":"Creatividad","t":"Anuncian un concurso de diseño. ¿Cuál es tu primera reacción?","o":[{"e":"filo","s":"espinas","t":"Me apunto para ganar; no voy a fingir que me conformo con participar."},{"e":"infinidad","s":"paso_helado","t":"Se me ocurren tantas ideas que preparo varias propuestas distintas a la vez."},{"e":"aspecto_igneo","s":"filo","t":"Me emociono y se lo cuento a todos; me lanzo con toda la energía."},{"e":"botin","s":"aspecto_igneo","t":"Reviso las bases y los premios; quiero conseguir todo lo que pueda ofrecerme."}]},{"b":4,"th":"Creatividad","t":"Tras semanas construyendo en Minecraft, una explosión abre un hueco enorme en tu obra.","o":[{"e":"eficiencia","s":"toque_seda","t":"Tapo el hueco rápido con lo que tenga a la mano y sigo adelante."},{"e":"reparacion","s":"lealtad","t":"Reconstruyo con paciencia cada rincón hasta que vuelva a lucir sana como antes."},{"e":"espinas","s":"proteccion","t":"Averiguo quién fue y dejo trampas: quien se meta con mi obra, se arrepiente."},{"e":"proteccion","s":"irrompibilidad","t":"Refuerzo muros e ilumino todo alrededor para que no vuelva a pasar nada."}]},{"b":4,"th":"Creatividad","t":"Un compañero te pide opinión sobre su trabajo creativo. ¿Cómo lo haces?","o":[{"e":"filo","s":"eficiencia","t":"Le digo directo qué falla y qué cambiaría, sin rodeos."},{"e":"toque_seda","s":"sigilo","t":"Reviso hasta el último detalle y lo ayudo a pulirlo sin cambiar su estilo."},{"e":"irrompibilidad","s":"reparacion","t":"Le propongo repetirlo cuantas veces haga falta; la práctica constante siempre lo mejora."},{"e":"eficiencia","s":"filo","t":"Le doy tres cambios concretos que mejoran más el resultado con menos esfuerzo."}]},{"b":4,"th":"Creatividad","t":"Un amigo quiere sacar adelante su idea y te pide ayuda. ¿Qué haces?","o":[{"e":"eficiencia","s":"toque_seda","t":"Armo un plan con pasos y fechas para terminarla sin perder tiempo."},{"e":"lealtad","s":"proteccion","t":"Me quedo a su lado el tiempo que haga falta, hasta el final."},{"e":"aspecto_igneo","s":"espinas","t":"Me emociono tanto con su idea que le contagio las ganas desde el primer minuto."},{"e":"toque_seda","s":"irrompibilidad","t":"Le ayudo a cuidar cada detalle para que quede exactamente como la imaginó."}]},{"b":4,"th":"Creatividad","t":"Cuando terminas una obra de la que estás orgulloso, ¿qué haces con ella?","o":[{"e":"sigilo","s":"espinas","t":"La enseño poco, solo a una o dos personas de total confianza."},{"e":"aspecto_igneo","s":"filo","t":"La muestro a todos con entusiasmo y no paro de hablar de ella."},{"e":"filo","s":"eficiencia","t":"La pongo a competir; quiero saber si de verdad supera a las demás."},{"e":"reparacion","s":"lealtad","t":"La uso para alegrarle el día a alguien que lo necesita."}]},{"b":5,"th":"Emociones y vínculos","t":"En plena discusión con alguien a quien quieres mucho, ¿qué haces?","o":[{"e":"espinas","s":"proteccion","t":"Puedo escuchar todo, pero que me falte al respeto no lo permito."},{"e":"toque_seda","s":"sigilo","t":"Elijo cada palabra con cuidado para no dañar lo que tenemos."},{"e":"paso_helado","s":"reparacion","t":"Respiro hondo, me pongo en su lugar y busco otra manera de entendernos."},{"e":"aspecto_igneo","s":"botin","t":"Digo lo que siento en el momento, con toda la intensidad y sin guardarme nada."}]},{"b":5,"th":"Emociones y vínculos","t":"Una amiga cercana atraviesa una racha muy mala. ¿Cómo la acompañas?","o":[{"e":"irrompibilidad","s":"reparacion","t":"Estoy ahí todos los días sin falta, el tiempo que haga falta."},{"e":"fortuna","s":"infinidad","t":"Le recuerdo que las rachas cambian y que algo bueno viene en camino."},{"e":"infinidad","s":"fortuna","t":"Le invento planes distintos y originales para sacarle una sonrisa."},{"e":"proteccion","s":"lealtad","t":"Me aseguro de que esté bien y le quito preocupaciones de encima."}]},{"b":5,"th":"Emociones y vínculos","t":"En tu mundo multijugador de Minecraft, alguien empieza a molestar a tu mejor amigo. ¿Qué haces?","o":[{"e":"lealtad","s":"aspecto_igneo","t":"Me pongo a su lado de inmediato y no lo suelto pase lo que pase."},{"e":"paso_helado","s":"sigilo","t":"Busco una salida tranquila que calme todo sin llegar a la pelea."},{"e":"espinas","s":"filo","t":"Le dejo claro que con mi amigo no se mete, y si insiste, responde."},{"e":"sigilo","s":"toque_seda","t":"Observo en silencio quién es y qué quiere antes de mover ficha."}]},{"b":5,"th":"Emociones y vínculos","t":"¿Cuál de estas frases describe mejor cómo demuestras cariño?","o":[{"e":"aspecto_igneo","s":"espinas","t":"Con entusiasmo: sorpresas, abrazos fuertes y muchísima energía cuando estamos juntos."},{"e":"proteccion","s":"lealtad","t":"Estando pendiente de que nada le falte y avisándole de posibles riesgos."},{"e":"irrompibilidad","s":"proteccion","t":"Con constancia: soy la misma persona confiable en los días buenos y malos."},{"e":"filo","s":"aspecto_igneo","t":"Con honestidad: le digo la verdad aunque cueste y lo animo a crecer."}]},{"b":5,"th":"Emociones y vínculos","t":"Conoces a alguien nuevo que te cae muy bien. ¿Cómo construyes esa amistad?","o":[{"e":"sigilo","s":"paso_helado","t":"Lo observo un buen rato y me abro poco a poco, cuando confío."},{"e":"espinas","s":"sigilo","t":"Dejo claro desde el inicio qué cosas acepto y cuáles no."},{"e":"reparacion","s":"proteccion","t":"Si algo sale mal entre nosotros, me encargo de arreglarlo pronto."},{"e":"botin","s":"fortuna","t":"Le hago mil preguntas para descubrir qué historias, gustos y secretos guarda."}]},{"b":5,"th":"Emociones y vínculos","t":"En Minecraft quieres sorprender a un amigo con un regalo especial. ¿Qué haces?","o":[{"e":"botin","s":"infinidad","t":"Exploro cuevas hasta juntar algo raro y valioso que nadie más tenga."},{"e":"fortuna","s":"botin","t":"Salgo sin plan, confiado en que me toparé con el regalo perfecto."},{"e":"sigilo","s":"toque_seda","t":"Observo qué necesita y lo dejo en su cofre sin que se entere."},{"e":"infinidad","s":"botin","t":"Invento algo único: una estatua, un juego o una sorpresa jamás vista."}]},{"b":5,"th":"Emociones y vínculos","t":"Un conocido te hace una broma pesada frente a todos. ¿Cómo reaccionas?","o":[{"e":"toque_seda","s":"eficiencia","t":"Sonrío para no arruinar el ambiente y luego se lo comento con delicadeza."},{"e":"filo","s":"aspecto_igneo","t":"Le contesto ahí mismo, claro y directo, que no me pareció gracioso."},{"e":"espinas","s":"filo","t":"Le devuelvo una broma igual de picante para que no la repita."},{"e":"reparacion","s":"lealtad","t":"Lo dejo pasar y luego busco que quedemos bien, sin rencores."}]},{"b":5,"th":"Emociones y vínculos","t":"Tu mejor amigo se va a vivir muy lejos. ¿Cómo lo vives?","o":[{"e":"paso_helado","s":"infinidad","t":"Lo tomo con calma y buscamos nuevas formas de seguir cerca."},{"e":"eficiencia","s":"irrompibilidad","t":"Armamos un calendario de llamadas y visitas para mantenernos siempre al día."},{"e":"toque_seda","s":"irrompibilidad","t":"Guardo nuestros recuerdos con mucho cuidado y le escribo cartas hechas con esmero."},{"e":"sigilo","s":"paso_helado","t":"Lo proceso en silencio y le escribo cuando tengo claras mis palabras."}]},{"b":5,"th":"Emociones y vínculos","t":"En Minecraft construyen juntos y tu amigo borra sin querer un muro importante. ¿Qué haces?","o":[{"e":"paso_helado","s":"reparacion","t":"Respiro y propongo adaptar el plano al nuevo hueco, sin drama."},{"e":"eficiencia","s":"irrompibilidad","t":"Reparto tareas rápido y reconstruimos el muro en pocos minutos."},{"e":"infinidad","s":"fortuna","t":"Aprovecho para proponer algo nuevo: ¿y si ahí va una torre loca?"},{"e":"irrompibilidad","s":"eficiencia","t":"Lo reconstruimos como sea, las veces que haga falta, hasta terminar."}]},{"b":5,"th":"Emociones y vínculos","t":"Alguien que quieres está muy nervioso por una presentación importante. ¿Cómo lo apoyas?","o":[{"e":"eficiencia","s":"toque_seda","t":"Le ayudo a organizar su tiempo y a ir directo a lo importante."},{"e":"aspecto_igneo","s":"espinas","t":"Lo lleno de ánimo con porras, abrazos y una energía contagiosa."},{"e":"lealtad","s":"aspecto_igneo","t":"Lo acompaño en persona y me quedo a su lado hasta que termine."},{"e":"filo","s":"eficiencia","t":"Le digo con franqueza dónde flaquea y lo reto a demostrar lo que vale."}]},{"b":6,"th":"Tiempo libre y gustos","t":"Tienes un sábado completamente libre y sin compromisos. ¿Cómo lo vives?","o":[{"e":"infinidad","s":"fortuna","t":"Arranco tres proyectitos nuevos a la vez y veo cuál se me enciende."},{"e":"irrompibilidad","s":"reparacion","t":"Avanzo otro poco en ese proyecto largo que llevo meses sin soltar."},{"e":"eficiencia","s":"filo","t":"Resuelvo mis pendientes en una hora y me quedo con el resto del día."},{"e":"fortuna","s":"botin","t":"Salgo sin plan, seguro que algo bueno se cruza en mi camino."}]},{"b":6,"th":"Tiempo libre y gustos","t":"Cuando juegas algo muy difícil, ¿cuál te describe mejor?","o":[{"e":"irrompibilidad","s":"proteccion","t":"Pierdo veinte veces y vuelvo a intentarlo; no suelto el reto hasta lograrlo."},{"e":"eficiencia","s":"filo","t":"Busco la estrategia más rápida y la practico hasta que me sale limpia."},{"e":"aspecto_igneo","s":"espinas","t":"Me emociono muchísimo, celebro cada avance y arrastro a todos a mirar."},{"e":"paso_helado","s":"infinidad","t":"Cambio de enfoque con calma hasta encontrar otra ruta que sí funcione."}]},{"b":6,"th":"Tiempo libre y gustos","t":"Noche de juegos de mesa con amigos. ¿Qué papel tomas?","o":[{"e":"proteccion","s":"lealtad","t":"Cuido que nadie se quede atrás y que el juego sea parejo."},{"e":"filo","s":"aspecto_igneo","t":"Voy por la victoria y les aviso de frente que pienso ganar."},{"e":"eficiencia","s":"irrompibilidad","t":"Leo las reglas rápido y organizo turnos para que todo fluya sin pausas."},{"e":"paso_helado","s":"sigilo","t":"Me acomodo a lo que salga y disfruto tranquilo cualquier giro."}]},{"b":6,"th":"Tiempo libre y gustos","t":"Es domingo y toca ordenar tu espacio de pasatiempos. ¿Qué haces?","o":[{"e":"espinas","s":"proteccion","t":"Dejo clara mi regla: este espacio es mío y nada se toca sin permiso."},{"e":"toque_seda","s":"eficiencia","t":"Acomodo cada pieza con cuidado, justo como debe estar, sin rayar ni doblar nada."},{"e":"filo","s":"espinas","t":"Tiro sin dudar lo que sobra y me digo la verdad: ya no lo uso."},{"e":"reparacion","s":"paso_helado","t":"Pego, coso y compongo lo que estaba roto; casi todo tiene salvación."}]},{"b":6,"th":"Tiempo libre y gustos","t":"Tienes una tarde libre dentro de tu mundo de Minecraft. ¿Qué haces?","o":[{"e":"irrompibilidad","s":"reparacion","t":"Sigo con mi túnel larguísimo, bloque a bloque, hasta ver el final."},{"e":"reparacion","s":"paso_helado","t":"Recorro la aldea restaurando casas dañadas y cuidando que todos estén bien."},{"e":"lealtad","s":"aspecto_igneo","t":"Invito a mis amigos a mi mundo; jugar acompañado es lo mejor."},{"e":"sigilo","s":"toque_seda","t":"Exploro solo y en silencio, observando todo antes de decidir qué hacer."}]},{"b":6,"th":"Tiempo libre y gustos","t":"Planean un viaje de fin de semana con amigos. ¿Cuál es tu papel?","o":[{"e":"proteccion","s":"lealtad","t":"Reviso que todos lleven lo necesario y que exista siempre un plan B."},{"e":"botin","s":"fortuna","t":"Quiero ver, probar y traerme de vuelta todo lo que pueda descubrir."},{"e":"toque_seda","s":"sigilo","t":"Elijo con cuidado cada lugar para que todo salga justo como lo imaginé."},{"e":"espinas","s":"sigilo","t":"Aviso mis límites desde el inicio: lo que no quiero hacer, no lo hago."}]},{"b":6,"th":"Tiempo libre y gustos","t":"Noche de películas con amigos. ¿Cómo participas?","o":[{"e":"filo","s":"espinas","t":"Digo sin rodeos si la película está floja; mi opinión siempre es honesta."},{"e":"infinidad","s":"botin","t":"Propongo mil ideas: maratón temático, juegos de adivinar, hasta inventar otro final."},{"e":"fortuna","s":"infinidad","t":"Elijo una al azar; algo me dice que hoy nos va a encantar."},{"e":"reparacion","s":"proteccion","t":"Me aseguro de que todos estén cómodos y animo a quien llegó decaído."}]},{"b":6,"th":"Tiempo libre y gustos","t":"Aparece una cueva enorme junto a tu base y tienes todo el día. ¿Cómo la tomas?","o":[{"e":"proteccion","s":"irrompibilidad","t":"Primero ilumino la entrada y aseguro la zona antes de que alguien pase."},{"e":"aspecto_igneo","s":"botin","t":"Entro corriendo, emocionadísimo, y llamo a todos a gritos para que me sigan."},{"e":"sigilo","s":"toque_seda","t":"Me asomo despacio, escucho y observo antes de dar un paso adentro."},{"e":"fortuna","s":"infinidad","t":"Entro confiado: hoy es de esos días en que todo sale a mi favor."}]},{"b":6,"th":"Tiempo libre y gustos","t":"Tus amigos arman un partido improvisado. ¿Cómo juegas?","o":[{"e":"filo","s":"eficiencia","t":"Juego fuerte para ganar y digo claro quién estuvo mejor al final."},{"e":"lealtad","s":"reparacion","t":"Lo que importa es mi equipo; me quedo con ellos hasta el último minuto."},{"e":"sigilo","s":"paso_helado","t":"Observo cómo se mueven todos y entro a la jugada en el momento justo."},{"e":"paso_helado","s":"reparacion","t":"Me adapto a cualquier posición y sigo tranquilo aunque se complique el marcador."}]},{"b":6,"th":"Tiempo libre y gustos","t":"Tienes un cofre grande y vacío en tu base de Minecraft. ¿Qué haces con él?","o":[{"e":"botin","s":"fortuna","t":"Lo lleno con todo lo raro que encuentre; quiero tener de todo siempre."},{"e":"infinidad","s":"fortuna","t":"Lo vuelvo mi taller de ideas: cada semana invento algo nuevo que construir."},{"e":"lealtad","s":"proteccion","t":"Lo dejo abierto para mis amigos, con regalos que sé que les servirán."},{"e":"espinas","s":"filo","t":"Lo dejo bien cerrado y aviso: quien lo abra sin permiso se las ve conmigo."}]},{"b":7,"th":"Valores y decisiones","t":"El grupo está dividido y te toca tomar una decisión importante. ¿Qué haces?","o":[{"e":"filo","s":"aspecto_igneo","t":"Digo claramente lo que pienso y defiendo mi postura hasta convencerlos."},{"e":"irrompibilidad","s":"eficiencia","t":"Mantengo mi decisión firme, aunque tarde más y se ponga difícil."},{"e":"sigilo","s":"paso_helado","t":"Escucho a todos en silencio y decido después de pensarlo a solas."},{"e":"infinidad","s":"botin","t":"Propongo una tercera opción que a nadie se le había ocurrido."}]},{"b":7,"th":"Valores y decisiones","t":"¿Qué es lo que más valoras en alguien que lidera un equipo?","o":[{"e":"filo","s":"espinas","t":"Que diga la verdad aunque incomode y no le tema a competir."},{"e":"infinidad","s":"botin","t":"Que tenga ideas nuevas y siempre encuentre otra manera de hacerlo."},{"e":"proteccion","s":"lealtad","t":"Que cuide a todos y piense en los riesgos antes de avanzar."},{"e":"eficiencia","s":"toque_seda","t":"Que organice bien, sea rápido y vaya directo a lo que funciona."}]},{"b":7,"th":"Valores y decisiones","t":"Te ofrecen mudarte a otra ciudad por una gran oportunidad. ¿Cómo decides?","o":[{"e":"botin","s":"infinidad","t":"Me emociona todo lo nuevo que podría conocer y conseguir; quiero más."},{"e":"paso_helado","s":"sigilo","t":"Me imagino adaptándome a lo que venga; siempre se encuentra el camino."},{"e":"lealtad","s":"proteccion","t":"Pienso primero en la gente que dejaría atrás y cuánto la extrañaría."},{"e":"toque_seda","s":"irrompibilidad","t":"Evalúo con calma qué cosas buenas de mi vida actual quiero conservar intactas."}]},{"b":7,"th":"Valores y decisiones","t":"En tu servidor, alguien vació tu cofre sin avisarte. ¿Qué haces?","o":[{"e":"reparacion","s":"lealtad","t":"Hablo con calma y propongo cómo arreglarlo juntos para recuperar la confianza."},{"e":"botin","s":"infinidad","t":"Negocio para recuperar lo mío y, si se puede, sacar algo extra."},{"e":"espinas","s":"filo","t":"Le marco un límite firme; si lo vuelve a cruzar, se lo devuelvo."},{"e":"infinidad","s":"paso_helado","t":"Lo dejo pasar; puedo conseguir más y ya tengo otro proyecto en mente."}]},{"b":7,"th":"Valores y decisiones","t":"Antes de decidir algo importante, ¿cuál es tu criterio principal?","o":[{"e":"fortuna","s":"botin","t":"Confío en que saldrá bien; casi siempre aparece una buena oportunidad."},{"e":"eficiencia","s":"toque_seda","t":"Elijo lo más práctico y rápido, porque mi tiempo vale mucho."},{"e":"aspecto_igneo","s":"filo","t":"Elijo lo que me apasiona, con todo el corazón y sin medias tintas."},{"e":"lealtad","s":"reparacion","t":"Elijo lo que no me aleje de las personas que quiero."}]},{"b":7,"th":"Valores y decisiones","t":"Te llega un dinero extra e inesperado. ¿Qué haces con él?","o":[{"e":"proteccion","s":"lealtad","t":"Guardo buena parte como colchón para que nada me tome desprevenido."},{"e":"irrompibilidad","s":"eficiencia","t":"Sigo mi plan de ahorro mes tras mes, sin rendirme aunque cueste."},{"e":"fortuna","s":"paso_helado","t":"Apuesto por una oportunidad que me emociona; confío en que valdrá la pena."},{"e":"infinidad","s":"fortuna","t":"Lo uso para arrancar un proyecto creativo nuevo; siempre hay otra idea."}]},{"b":7,"th":"Valores y decisiones","t":"Te invitan a un servidor con reglas que no te convencen del todo. ¿Qué decides?","o":[{"e":"botin","s":"aspecto_igneo","t":"Entro de todos modos a curiosear; seguro hay cosas interesantes por descubrir."},{"e":"espinas","s":"sigilo","t":"Pongo mis condiciones claras y, si no las respetan, me retiro."},{"e":"paso_helado","s":"reparacion","t":"Me adapto con calma a su forma de jugar y busco mi lugar."},{"e":"toque_seda","s":"irrompibilidad","t":"No toco nada hasta entender bien cómo cuidan lo que ya construyeron."}]},{"b":7,"th":"Valores y decisiones","t":"Descubres que un compañero hizo trampa y nadie más lo sabe. ¿Qué haces?","o":[{"e":"filo","s":"espinas","t":"Lo enfrento directamente y le digo lo que pienso, sin rodeos."},{"e":"proteccion","s":"lealtad","t":"Me aseguro de que nadie salga perjudicado y prevengo que vuelva a pasar."},{"e":"reparacion","s":"proteccion","t":"Hablo con él en privado para ayudarle a enmendarlo y recomponer todo."},{"e":"sigilo","s":"espinas","t":"Observo en silencio un tiempo y reúno datos antes de actuar."}]},{"b":7,"th":"Valores y decisiones","t":"Eres responsable de una aldea con pocos recursos. ¿En qué los inviertes primero?","o":[{"e":"fortuna","s":"infinidad","t":"En crecer hacia donde se ven más oportunidades; confío en que resultará."},{"e":"reparacion","s":"proteccion","t":"En curar y reconstruir lo que se dañó antes de seguir creciendo."},{"e":"proteccion","s":"irrompibilidad","t":"En murallas y vigilancia para que nadie de la aldea corra peligro."},{"e":"irrompibilidad","s":"eficiencia","t":"En un proyecto largo y sólido que siga firme pase lo que pase."}]},{"b":7,"th":"Valores y decisiones","t":"¿Qué te haría cambiar de opinión sobre algo que ya habías decidido?","o":[{"e":"reparacion","s":"lealtad","t":"Notar que mi decisión lastimó a alguien; prefiero corregir el rumbo y sanar eso."},{"e":"lealtad","s":"aspecto_igneo","t":"Que alguien de mi gente me pida sinceramente que lo reconsidere."},{"e":"sigilo","s":"toque_seda","t":"Notar con calma un detalle importante que antes no había visto."},{"e":"aspecto_igneo","s":"filo","t":"Encontrar algo que me apasione más y me encienda de verdad."}]}]};
